CREATE TABLE process_changes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_id BIGINT UNSIGNED NOT NULL, version BIGINT UNSIGNED NOT NULL, kind VARCHAR(32) CHARACTER SET ascii NOT NULL, field VARCHAR(2100) NOT NULL, before_data MEDIUMTEXT NOT NULL, after_data MEDIUMTEXT NOT NULL, FOREIGN KEY(process_id,version) REFERENCES process_versions(process_id,version), INDEX process_diff(process_id,version,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
